import { createHash } from 'node:crypto';
import type { PrismaClient } from '../../generated/prisma/client.js';

/**
 * Identity repository: `sessions` (global table, no RLS — ADR-0004 A-4).
 *
 * Sessions are opaque and server-side: the client holds a raw token, the database
 * stores only its SHA-256 hash. The raw token is generated by the caller (the auth
 * route) and never passed to this module — only the hash is.
 *
 * TTL contract (ADR-0004 A-5): 12 h idle / 30 d absolute. The caller computes both
 * deadlines and passes them in; this module stores what it is given.
 */

/** SHA-256 of the raw session token, hex-encoded (64 chars). */
export function hashToken(rawToken: string): string {
  return createHash('sha256').update(rawToken, 'utf8').digest('hex');
}

export interface CreateSessionInput {
  readonly userId: string;
  /** SHA-256 hex of the raw token (from `hashToken`). */
  readonly tokenHash: string;
  readonly expiresAt: Date;
  readonly idleExpiresAt: Date;
  /** The tenant the user is currently working in, once chosen. */
  readonly activeTenantId?: string;
  /** The session this one replaced (rotation chain). */
  readonly rotatedFromId?: string;
}

export async function createSession(client: PrismaClient, input: CreateSessionInput) {
  return client.session.create({
    data: {
      userId: input.userId,
      tokenHash: input.tokenHash,
      expiresAt: input.expiresAt,
      idleExpiresAt: input.idleExpiresAt,
      lastSeenAt: new Date(),
      ...(input.activeTenantId === undefined ? {} : { activeTenantId: input.activeTenantId }),
      ...(input.rotatedFromId === undefined ? {} : { rotatedFromId: input.rotatedFromId }),
    },
  });
}

export interface SessionLookupResult {
  readonly id: string;
  readonly userId: string;
  readonly activeTenantId: string | null;
  readonly expiresAt: Date;
  readonly idleExpiresAt: Date;
  readonly revokedAt: Date | null;
}

/**
 * Find a live session by token hash.
 *
 * Returns `undefined` when the hash does not match any row. Expired and revoked
 * sessions are returned as-is — the caller decides (and revokes) based on the
 * deadlines, so the response time does not leak whether a session existed.
 */
export async function findSessionByTokenHash(
  client: PrismaClient,
  tokenHash: string,
): Promise<SessionLookupResult | undefined> {
  const row = await client.session.findUnique({
    where: { tokenHash },
    select: {
      id: true,
      userId: true,
      activeTenantId: true,
      expiresAt: true,
      idleExpiresAt: true,
      revokedAt: true,
    },
  });

  return row ?? undefined;
}

/** Bump `lastSeenAt` (idle-timeout bookkeeping). */
export async function touchSession(client: PrismaClient, sessionId: string): Promise<void> {
  await client.session.update({
    where: { id: sessionId },
    data: { lastSeenAt: new Date() },
  });
}

/** Revoke a single session (logout). */
export async function revokeSession(client: PrismaClient, sessionId: string): Promise<void> {
  await client.session.update({
    where: { id: sessionId },
    data: { revokedAt: new Date() },
  });
}

/** Revoke every live session for a user (logout-everywhere / password change). */
export async function revokeAllSessions(client: PrismaClient, userId: string): Promise<number> {
  const result = await client.session.updateMany({
    where: { userId, revokedAt: null },
    data: { revokedAt: new Date() },
  });

  return result.count;
}
